def group_and_sort_products(product_list):
    groups = {}
    for category, name, units in product_list:
        if category not in groups:
            groups[category] = []
        groups[category].append((name, units))
    for category in groups:
        groups[category].sort(key=lambda x: x[0])
    return groups
